using System;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonCustomerDirectorySetup
    {
        static T Copy<T>(T source,Transform root,Transform target) where T:Component{return target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();}
        static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);}
        static Button Button(Transform parent,string name,float x,float y,float w,float h){var g=DefaultControls.CreateButton(new DefaultControls.Resources());g.name=name;g.transform.SetParent(parent,false);Place(g.GetComponent<RectTransform>(),x,y,w,h);var text=g.GetComponentInChildren<Text>();text.font=ContentPreviewLayout.LoadFont();text.fontSize=18;text.supportRichText=false;return g.GetComponent<Button>();}
        static GameObject Box(Transform parent,string name,float x,float y,float w,float h){var g=new GameObject(name,typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);Place(g.GetComponent<RectTransform>(),x,y,w,h);g.GetComponent<Image>().color=new Color(.93f,.94f,.89f);return g;}
        [MenuItem("Cat Cafe/開発用/UI再生成/お客さんの名簿",false,35)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();var source=preview.GetComponent<PythonDayOffPanel>();var root=source.panel.transform.parent;var old=root.Find("Customer Directory");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);
            var p=preview.GetComponent<PythonCustomerDirectoryPanel>() ?? preview.gameObject.AddComponent<PythonCustomerDirectoryPanel>();p.panel=UnityEngine.Object.Instantiate(source.panel,root);p.panel.name="Customer Directory";var s=source.panel.transform;var t=p.panel.transform;
            p.title=Copy(source.title,s,t);p.details=Copy(source.details,s,t);p.notice=Copy(source.notice,s,t);p.close=Copy(source.close,s,t);var card=p.close.transform.parent;
            UnityEngine.Object.DestroyImmediate(t.Find(AnimationUtility.CalculateTransformPath(source.confirmation.transform,s)).gameObject);UnityEngine.Object.DestroyImmediate(Copy(source.proceed,s,t).gameObject);
            p.today=Button(card,"Today",24,78,280,40);p.tomorrow=Button(card,"Tomorrow",320,78,280,40);p.adopted=Button(card,"Show Adopted",616,78,300,40);Bind(p.today,p.Today);Bind(p.tomorrow,p.Tomorrow);Bind(p.adopted,p.ToggleAdopted);Bind(p.close,p.Close);Place(p.close.GetComponent<RectTransform>(),24,550,892,40);
            var detailsScroll=p.details.transform.parent.parent.GetComponent<ScrollRect>();Place(detailsScroll.GetComponent<RectTransform>(),372,130,544,352);Place(detailsScroll.viewport,6,6,514,340);detailsScroll.verticalScrollbar.GetComponent<RectTransform>().sizeDelta=new Vector2(12,340);p.details.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal,514);p.details.fontSize=17;
            var area=Box(card,"Customers Scroll",24,130,332,352);var scroll=area.AddComponent<ScrollRect>();scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;var viewport=Box(area.transform,"Viewport",0,0,312,352);viewport.AddComponent<Mask>().showMaskGraphic=false;scroll.viewport=viewport.GetComponent<RectTransform>();var content=new GameObject("Content",typeof(RectTransform));content.transform.SetParent(viewport.transform,false);Place(content.GetComponent<RectTransform>(),0,0,312,352);p.listContent=scroll.content=content.GetComponent<RectTransform>();
            var bar=DefaultControls.CreateScrollbar(new DefaultControls.Resources());bar.transform.SetParent(area.transform,false);Place(bar.GetComponent<RectTransform>(),318,0,12,352);scroll.verticalScrollbar=bar.GetComponent<Scrollbar>();scroll.verticalScrollbar.direction=Scrollbar.Direction.BottomToTop;
            p.entryPrefab=Button(card,"Customer Entry Template",0,0,304,88);p.entryPrefab.GetComponentInChildren<Text>().fontSize=16;p.entryPrefab.GetComponentInChildren<Text>().alignment=TextAnchor.MiddleLeft;p.entryPrefab.gameObject.SetActive(false);
            p.panel.SetActive(false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);PythonEventListSetup.Build();Debug.Log("CAT_CAFE_CUSTOMER_DIRECTORY_UI_OK");
        }
        public static void BuildAndVerify()
        {
            Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);
            var state=PythonServiceSetup.Sample();state.instance_id="directory-test";state.customer_directory=new PythonCustomerDirectory{today_label="1日目（月）",tomorrow_label="2日目（火）",notes="予定は営業した場合の進行時点です（0刻＝開店時）。休業日は来店しません。\n来店回数は営業セーブ内の記録です。未接客の来店も含みます。",rows=new[]{new PythonDirectoryCustomer{customer_id="guest-1",name="佐藤さん",visits=2,preference_text="白猫好き",today="来店予定 / 0刻",tomorrow="予定なし",details="佐藤さん / 通常のお客さん\n白猫好き / 来店曜日：月・水・金\n\n来店回数：2回\n今日：来店予定 / 0刻\n翌日：予定なし\n\n常連度：20/50\n累積不満：0/20\n信頼状態：通常\n直近の接客評価：満足 / 点数4",cats=new[]{new PythonCustomerMatch{cat_id="mike",details="ミケ / 猫から客への親しみ10\n一致なし / 通常のテンション上昇×1 / 出勤予定・健康"},new PythonCustomerMatch{cat_id="old",adopted=true,details="譲渡済みの猫 / 親しみ5"}}},new PythonDirectoryCustomer{customer_id="advanced-longhair",name="坂本さん",preference_text="長毛好き",today="未解放（人気第2段階）",tomorrow="未解放（人気第2段階）",details="坂本さん / 長毛好きのお客さん\n来店曜日：毎営業日10％\n\n長毛の猫を担当し、触れ合いの条件を満たすと追加料金を獲得します。\n条件結果：接客記録はまだありません。",cats=new PythonCustomerMatch[0]}}};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();var p=preview.GetComponent<PythonCustomerDirectoryPanel>();var list=preview.GetComponent<PythonEventListPanel>();list.Open();if(list.entries.Length!=23 || !list.entries[19].interactable)throw new Exception("Customer directory entry missing");list.CustomerDirectory();if(list.panel.activeSelf || !p.panel.activeSelf || p.SelectedCustomer!="guest-1" || !p.details.text.Contains("常連度") || p.details.text.Contains("譲渡済みの猫"))throw new Exception("Directory navigation/details failed");Capture(preview,"Logs/CustomerDirectory.png");
            p.Tomorrow();if(!p.listContent.GetChild(0).GetComponentInChildren<Text>().text.Contains("予定なし") || p.SelectedCustomer!="guest-1")throw new Exception("Tomorrow directory failed");p.ToggleAdopted();if(!p.details.text.Contains("譲渡済みの猫"))throw new Exception("Adopted match filter failed");p.Select("advanced-longhair");if(!p.details.text.Contains("接客記録はまだ") || !p.details.text.Contains("長毛"))throw new Exception("Special customer detail failed");Capture(preview,"Logs/CustomerDirectorySpecial.png");
            state.revision++;apply();if(p.SelectedCustomer!="advanced-longhair")throw new Exception("Directory selection lost across revision");p.Disconnect();if(p.tomorrow.interactable || p.adopted.interactable || p.listContent.GetChild(0).GetComponent<Button>().interactable)throw new Exception("Offline directory controls enabled");apply();state.instance_id="loaded";state.customer_directory.rows=new[]{state.customer_directory.rows[0]};apply();if(p.panel.activeSelf || p.SelectedCustomer!="guest-1" || p.listContent.GetChild(1).gameObject.activeSelf)throw new Exception("Directory retained across load");p.Open();if(p.details.text.Contains("譲渡済みの猫"))throw new Exception("Adopted filter retained across load");state.customer_directory.rows=new PythonDirectoryCustomer[0];state.revision++;apply();if(!p.details.text.Contains("記録はありません"))throw new Exception("Empty directory failed");if(typeof(PythonStateClient).GetField("pending",f).GetValue(client)!=null)throw new Exception("Directory browsing queued command");Debug.Log("CAT_CAFE_CUSTOMER_DIRECTORY_DISPLAY_OK");
        }
        static void Capture(ContentPreview preview,string path){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,path});}
    }
